const touchSessionFoundTool = `-- name: TouchSessionFoundTool :exec
INSERT INTO session_found_tools (session_pk, template_ns, template_name, upstream_name, found_at)
VALUES ($1, $2, $3, $4, clock_timestamp())
ON CONFLICT (session_pk, template_ns, template_name, upstream_name) DO UPDATE SET found_at = clock_timestamp()
`

type TouchSessionFoundToolParams struct {
	SessionPk    int64
	TemplateNs   string
	TemplateName string
	UpstreamName string
}

func (q *Queries) TouchSessionFoundTool(ctx context.Context, arg TouchSessionFoundToolParams) error {
	_, err := q.db.Exec(ctx, touchSessionFoundTool,
		arg.SessionPk,
		arg.TemplateNs,
		arg.TemplateName,
		arg.UpstreamName,
	)
	return err
}

const trimSessionFoundTools = `-- name: TrimSessionFoundTools :exec
DELETE FROM session_found_tools AS t
WHERE t.session_pk = $1
  AND (t.template_ns, t.template_name, t.upstream_name) NOT IN (
    SELECT f.template_ns, f.template_name, f.upstream_name FROM session_found_tools f
    WHERE f.session_pk = $1
    ORDER BY f.found_at DESC, f.template_name, f.upstream_name
    LIMIT $2::int)
`

type TrimSessionFoundToolsParams struct {
	SessionPk int64
	Keep      int32
}

// Keeps the newest @keep found tools of a session.
func (q *Queries) TrimSessionFoundTools(ctx context.Context, arg TrimSessionFoundToolsParams) error {
	_, err := q.db.Exec(ctx, trimSessionFoundTools, arg.SessionPk, arg.Keep)
	return err
}

const upsertToolCatalog = `-- name: UpsertToolCatalog :exec
INSERT INTO tool_catalog (template_uid, generation, template_ns, template_name, tools, instance_id)
SELECT $1::text, $2::bigint, $3::text, $4::text, $5::jsonb, $6::text
WHERE octet_length(($5::jsonb)::text) <= 1048576
ON CONFLICT (template_uid, generation) DO UPDATE
SET template_ns = EXCLUDED.template_ns, template_name = EXCLUDED.template_name,
    tools = EXCLUDED.tools, instance_id = EXCLUDED.instance_id, learned_at = now()
`

type UpsertToolCatalogParams struct {
	TemplateUid  string
	Generation   int64
	TemplateNs   string
	TemplateName string
	Tools        []byte
	InstanceID   string
}

// A list whose stored form is over 1 MiB is not learned.
func (q *Queries) UpsertToolCatalog(ctx context.Context, arg UpsertToolCatalogParams) error {
	_, err := q.db.Exec(ctx, upsertToolCatalog,
		arg.TemplateUid,
		arg.Generation,
		arg.TemplateNs,
		arg.TemplateName,
		arg.Tools,
		arg.InstanceID,
	)
	return err
}
